"OLAYLAR_ARKEOLOJI_D2_ITALYA_AVRUPA:-1549-01-01:0":{"b": ["El Argar (çanda Argar, Antas): çand bi dawî dibe (texmînî)", "0272e861"], "d": ["Li Îberyaya Başûrê Rojhilat civakeke Serdema Bronz a sê qonaxî, bi niştecihbûnên li ser giran, di asta dewleta pêşîn de; di lûtkeya xwe de ~35.000 km2.", "3b8cc665"]},
"OLAYLAR_ARKEOLOJI_D2_ITALYA_AVRUPA:-2166-01-01:0":{"b": ["Los Millares: niştecihbûn bi dawî dibe", "cd3a1b70"], "d": ["Li Îberyaya Başûrê Rojhilat niştecihbûna bi sûr a Serdema Sifir û nekropola megalîtîk; xelekên sûran di destpêka hezarsala 3. de, 'forts' piştî ca. B.Z. 2500, terikandin dora ca. B.Z. 2200.", "f9ea939a"]},
